create table xxventuri.xxeba_sales_order_bkp_08_sep_2025 (
    order_id               number,
    deal_id                number,
    customer_id            number,
    territory_id           number,
    sales_rep              number,
    po_number              varchar2(100 byte),
    po_date                date,
    reference              varchar2(100 byte),
    billing_location       number,
    delivery_location      number,
    order_frequency        number,
    next_order_date        date,
    created                timestamp(6) with local time zone,
    created_by             varchar2(50 byte),
    updated                timestamp(6) with local time zone,
    updated_by             varchar2(50 byte),
    status                 varchar2(10 byte),
    order_number           number,
    order_date             date,
    order_repeat           varchar2(1 byte),
    latitude               varchar2(100 byte),
    longitude              varchar2(100 byte),
    last_updated_latitude  varchar2(100 byte),
    last_updated_longitude varchar2(100 byte),
    remarks                varchar2(100 byte),
    export_flag            char(1 byte),
    created_temp           varchar2(100 byte),
    updated_temp           varchar2(100 byte),
    tally_reference_number varchar2(100 byte),
    updated_in_tally       varchar2(1 byte),
    approver_comments      varchar2(4000 byte),
    transaction_id         number,
    source_application     char(1 byte),
    order_type_id          number,
    account_owner_id       number
);


